import { test, expect } from 'bun:test';
import { splitByWeights } from '../src/split.js';
test('splits by weight', () => expect(splitByWeights(1000, [50, 30, 20])).toEqual([500, 300, 200]));
test('equal weights', () => expect(splitByWeights(100, [1, 1, 1, 1])).toEqual([25, 25, 25, 25]));
test('single payee gets everything', () => expect(splitByWeights(777, [3])).toEqual([777]));

