import { test, expect } from 'bun:test';
import { splitByWeights } from '../src/split.js';
const cases = [[100, [1, 1, 1]], [1, [1, 1, 1]], [5, [1, 1]], [999, [50, 30, 20]], [10, [1, 1, 1, 1, 1, 1, 1]], [1001, [7, 3, 3]]];
test('shares are whole cents and sum exactly to the total', () => {
  for (const [total, weights] of cases) {
    const shares = splitByWeights(total, weights);
    expect(shares.length).toBe(weights.length);
    expect(shares.every((s) => Number.isInteger(s) && s >= 0)).toBe(true);
    expect(shares.reduce((a, b) => a + b, 0)).toBe(total);
  }
});
test('each share is within one cent of its exact proportion', () => {
  for (const [total, weights] of cases) {
    const w = weights.reduce((a, b) => a + b, 0);
    splitByWeights(total, weights).forEach((s, i) => expect(Math.abs(s - (total * weights[i]) / w)).toBeLessThan(1));
  }
});
